package com.mazkiplay.nusantara;
import android.graphics.*;import android.view.*;import java.util.*;
public class MarketChartView extends View{private ArrayList<ForexAgent.Candle>d=new ArrayList<>();private Paint p=new Paint(3);public MarketChartView(android.content.Context c){super(c);}public void setData(ArrayList<ForexAgent.Candle>x){d=x==null?new ArrayList<>():x;invalidate();}protected void onDraw(Canvas c){c.drawColor(Color.rgb(10,11,14));if(d.size()<2)return;int n=Math.min(90,d.size()),st=d.size()-n;float h=getHeight(),w=getWidth(),top=12,bottom=h-28,gap=Math.max(5,(w-20)/n);double lo=Double.MAX_VALUE,hi=-Double.MAX_VALUE;for(int i=st;i<d.size();i++){lo=Math.min(lo,d.get(i).low);hi=Math.max(hi,d.get(i).high);}double span=Math.max(hi-lo,1e-9);for(int i=st;i<d.size();i++){ForexAgent.Candle x=d.get(i);float xx=10+(i-st)*gap,yh=top+(float)((hi-x.high)/span)*(bottom-top),yl=top+(float)((hi-x.low)/span)*(bottom-top),yo=top+(float)((hi-x.open)/span)*(bottom-top),yc=top+(float)((hi-x.close)/span)*(bottom-top);p.setColor(x.close>=x.open?Color.rgb(50,210,150):Color.rgb(240,90,100));c.drawLine(xx,yh,xx,yl,p);c.drawRect(xx-4,Math.min(yo,yc),xx+4,Math.max(Math.min(yo,yc)+2,Math.max(yo,yc)),p);}p.setColor(Color.LTGRAY);p.setTextSize(11);c.drawText("Candlestick • public market feed • manual view",10,h-10,p);}public boolean onTouchEvent(MotionEvent e){return true;}}
